mapper.select:
select hb.bed_id, hb.room_id, hb.bed_no, hb.bed_status, hr.dept, hr.location
from hospital_bed hb
join hospital_room hr on hb.room_id = hr.room_id


        AND hb.room_id = #{req.roomId}


        AND bed_status = #{req.bedStatus}


        AND dept = #{req.dept}


order by hb.room_id, hb.bed_no
limit #{offset}, #{pageSize}

select count(*)
from hospital_bed hb join hospital_room hr on hb.room_id = hb.room_id


        AND hb.room_id = #{req.roomId}


        AND bed_status = #{req.bedStatus}


        AND dept = #{req.dept}
